def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find solid lines and the color whose internal lines most evenly divide
    # the grid into repeated regions.
    line_positions = {}
    for color in range(10):
        rows = [r for r in range(h) if all(v == color for v in grid[r])]
        cols = [c for c in range(w) if all(grid[r][c] == color for r in range(h))]
        if rows or cols:
            line_positions[color] = (rows, cols)

    def balance(n, lines):
        lines = sorted(x for x in lines if 0 < x < n - 1)
        if not lines:
            return 0.0
        sizes = [lines[0]]
        sizes.extend(lines[i] - lines[i - 1] - 1 for i in range(1, len(lines)))
        sizes.append(n - 1 - lines[-1])
        mean = sum(sizes) / len(sizes)
        return sum((x - mean) ** 2 for x in sizes) / len(sizes)

    def separator_score(item):
        color, (rows, cols) = item
        internal = [x for x in rows if 0 < x < h - 1] + [
            x for x in cols if 0 < x < w - 1
        ]
        return (len(internal), -(balance(h, rows) + balance(w, cols)))

    sep, (row_lines, col_lines) = max(line_positions.items(), key=separator_score)

    def regions(n, lines):
        result, start = [], 0
        for x in sorted(lines):
            if start < x:
                result.append((start, x))
            start = x + 1
        if start < n:
            result.append((start, n))
        return result

    row_regions = regions(h, row_lines)
    col_regions = regions(w, col_lines)

    counts = {}
    for row in grid:
        for v in row:
            if v != sep:
                counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # Use the region containing the most non-background marks as the template.
    source = None
    best = -1
    for ri, (r0, r1) in enumerate(row_regions):
        for ci, (c0, c1) in enumerate(col_regions):
