def transform(grid):
    h, w = len(grid), len(grid[0])

    counts = [0] * 10
    for row in grid:
        for value in row:
            counts[value] += 1
    background = max(range(10), key=lambda value: counts[value])

    # Separator color appears as a complete row or column, but is not the
    # most common background color.
    candidates = []
    for color in range(10):
        if color == background:
            continue
        rows = [r for r in range(h) if all(v == color for v in grid[r])]
        cols = [c for c in range(w) if all(grid[r][c] == color for r in range(h))]
        if rows or cols:
            candidates.append((len(rows) + len(cols), color, rows, cols))

    if not candidates:
        return [row[:] for row in grid]

    _, separator, row_lines, col_lines = max(candidates)

    def regions(length, lines):
        result = []
        start = 0
        for line in sorted(lines):
            if start < line:
                result.append((start, line))
            start = line + 1
        if start < length:
            result.append((start, length))
        return result

    row_regions = regions(h, row_lines)
    col_regions = regions(w, col_lines)

    # The region containing the most marks supplies the pattern copied to
    # every other region.
    source = None
    most_marks = -1
    for ri, (r0, r1) in enumerate(row_regions):
        for ci, (c0, c1) in enumerate(col_regions):
            marks = sum(
                grid[r][c] != background and grid[r][c] != separator
                for r in range(r0, r1)
                for c in range(c0, c1)
            )
            if marks > most_marks:
                most_marks = marks
                source = (ri, ci)

    sri, sci = source
    sr0, sr1 = row_regions[sri]
    sc0, sc1 = col_regions[sci]
    pattern = [grid[r][sc0:sc1] for r in range(sr0, sr1)]

    out = [row[:] for row in grid]
    for r0, r1 in row_regions:
        for c0, c1 in col_regions:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = pattern[(r - r0) % len(pattern)][(c - c0) % len(pattern[0])]
    return out
